    kappaPrev = kappa;
    const margin = 2 * Fn + t;
    if (t >= 18 && margin < minMargin) { minMargin = margin; minMarginAt = t; }
    if (t >= 1000 && -Fn / t > maxSpeed) { maxSpeed = -Fn / t; maxSpeedAt = t; }
